#include <stdio.h>
#include <stdlib.h>
#include <inttypes.h>

/*
 * Character-frequency histogram over a generated byte buffer (256-bucket
 * count array). Stand-in for "string processing" -- sequential byte
 * iteration with a data-dependent, unpredictable-to-the-branch-predictor
 * bucket index, contrasting with quicksort/lcs's numeric-array/DP access
 * patterns. Buffer is filled with splitmix64 (public domain, Vigna), same
 * generator as the lcs benchmark, reduced mod 256 for a full-byte-range
 * (not small-alphabet) distribution.
 */
static uint64_t splitmix64(uint64_t x) {
    x += 0x9E3779B97F4A7C15ULL;
    x = (x ^ (x >> 30)) * 0xBF58476D1CE4E5B9ULL;
    x = (x ^ (x >> 27)) * 0x94D049BB133111EBULL;
    x = x ^ (x >> 31);
    return x;
}

static void fill(uint8_t *buf, int32_t n) {
    for (int32_t i = 0; i < n; i++) {
        uint64_t idx = (uint64_t)(i + 1);
        buf[i] = (uint8_t)(splitmix64(idx) % 256);
    }
}

static void histogram(const uint8_t *buf, int32_t n, uint64_t *counts) {
    for (int32_t b = 0; b < 256; b++) counts[b] = 0;
    for (int32_t i = 0; i < n; i++) {
        counts[buf[i]]++;
    }
}

static uint64_t checksum(const uint64_t *counts) {
    uint64_t sum = 0;
    for (int32_t b = 0; b < 256; b++) {
        sum += counts[b] * (uint64_t)(b + 1);
    }
    return sum;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <n>\n", argv[0]);
        return 1;
    }
    int32_t n = (int32_t)strtol(argv[1], NULL, 10);

    if (n <= 0) {
        printf("%" PRIu64 "\n", (uint64_t)0);
        return 0;
    }

    uint8_t *buf = malloc((size_t)n);
    if (!buf) {
        fprintf(stderr, "malloc failed\n");
        return 1;
    }

    fill(buf, n);
    uint64_t counts[256];
    histogram(buf, n, counts);
    uint64_t result = checksum(counts);
    free(buf);

    printf("%" PRIu64 "\n", result);
    return 0;
}
